已知我們採用隨機梯度下降法來進行更新，且學習率為 0.10.1，則

{W1new=W1−0.1×G1W2new=W2−0.1×G2\begin{cases}
    W_1^{new} = W_1 - 0.1 \times G_1 \\
    W_2^{new} = W_2 - 0.1 \times G_2 \\
\end{cases}

W1new=W1−0.1×G1=[−10−111−1]−0.1×[−610−1120260]=[−10−111−1]−[−0.61−1.122.60]=[−0.4−10.1−1−1.6−1]\begin{equation}
    \begin{aligned}
        W_1^{new}
        &amp;= 
            W_1 - 0.1 \times G_1
            \\\\
        &amp;= 
            \begin{bmatrix}
                -1 &amp; 0 \\
                -1 &amp; 1 \\
                1 &amp; -1 \\
            \end{bmatrix}
            - 0.1 \times
            \begin{bmatrix}
                -6 &amp; 10  \\
                -11 &amp; 20 \\
                26 &amp; 0   \\
            \end{bmatrix}
            \\\\
        &amp;= 
            \begin{bmatrix}
                -1 &amp; 0 \\
                -1 &amp; 1 \\
                1 &amp; -1 \\
            \end{bmatrix}
            - 
            \begin{bmatrix}
                -0.6 &amp; 1  \\
                -1.1 &amp; 2  \\
                2.6 &amp; 0   \\
            \end{bmatrix}
            \\\\
        &amp;= 
            \begin{bmatrix}
                -0.4 &amp; -1 \\
                0.1 &amp; -1  \\
                -1.6 &amp; -1 \\
            \end{bmatrix}
    \end{aligned}
\end{equation}

W2new=W2−0.1×G2=[1−2]−0.1×[43−10]=[−10−111−1]−[4.3−1]=[−3.3−1]\begin{equation}
    \begin{aligned}
        W_2^{new}
        &amp;= 
            W_2 - 0.1 \times G_2
            \\\\
        &amp;= 
            \begin{bmatrix}
                1  \\
                -2 \\
            \end{bmatrix}
            - 0.1 \times
            \begin{bmatrix}
                43   \\
                -10  \\
            \end{bmatrix}
            \\\\
        &amp;= 
            \begin{bmatrix}
                -1 &amp; 0 \\
                -1 &amp; 1 \\
                1 &amp; -1 \\
            \end{bmatrix}
            - 
            \begin{bmatrix}
                4.3 \\
                -1  \\
            \end{bmatrix}
            \\\\
        &amp;= 
            \begin{bmatrix}
                -3.3 \\
                -1   \\
            \end{bmatrix}
    \end{aligned}
\end{equation}

